import{_ as t,b as a,e as r,a8 as o}from"./chunks/framework.CD0vREyi.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomResampler","kind":"Class","declaration":"TCustomResampler = class(TCustomSampler)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TCustomSampler","TCustomResampler"],"summary":"Abstract base class for pixel resampling and filtering algorithms attached to `TBitmap32`.","date":1787737575000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomResampler/index.md","filePath":"api/GR32/TCustomResampler/index.md","lastUpdated":1787737575000,"timestamp":1787737575000,"datetime":"2026-08-26T09:46:15.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),s={name:"api/GR32/TCustomResampler/index.md"};function d(i,e,c,n,p,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomResampler</code> is the abstract base class for all bitmap resamplers in Graphics32. It inherits from <code>TCustomSampler</code> and adapts generic sub-pixel color sampling specifically for <code>TCustomBitmap32</code> instances.</p><p>Resamplers provide spatial filtering and interpolation algorithms (such as Nearest Neighbor, Linear, Cubic, or Kernel resamplers) used when stretching, transforming, or sampling bitmaps.</p><p>The <code>Bitmap</code> property associates the resampler with its source bitmap. The <code>PixelAccessMode</code> property controls out-of-bounds pixel sampling behavior (<code>pamUnsafe</code>, <code>pamSafe</code>, <code>pamWrap</code>, or <code>pamTransparentEdge</code>).</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Constructors/Create">Create</a></td><td>Initializes a new <code>TCustomResampler</code> instance, optionally attaching it to a source bitmap.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Resample">Resample</a></td><td>Protected virtual abstract method that resamples a source bitmap area into a destination bitmap area.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/Bitmap">Bitmap</a></td><td><code>TCustomBitmap32</code></td><td>Public</td><td>The source bitmap associated with this resampler.</td></tr><tr><td><a href="./Properties/Width">Width</a></td><td><code>TFloat</code></td><td>Public</td><td>Read-only effective kernel sampling width.</td></tr><tr><td><a href="./Properties/PixelAccessMode">PixelAccessMode</a></td><td><code>TPixelAccessMode</code></td><td>Published</td><td>Boundary handling mode (<code>pamUnsafe</code>, <code>pamSafe</code>, <code>pamWrap</code>, <code>pamTransparentEdge</code>).</td></tr></tbody></table>',10)])])}const u=t(s,[["render",d]]);export{h as __pageData,u as default};
